mapper.select:


    AND t.direction = #{q.direction}
    AND t.status = #{q.status}
    AND t.account_id = #{q.accountId}

        AND EXISTS (SELECT 1 FROM fin_io_doc_item x WHERE x.doc_id = t.id AND x.category_id = #{q.categoryId})


        AND (t.doc_no LIKE CONCAT('%', #{q.keyword}, '%') OR t.ticket_no LIKE CONCAT('%', #{q.keyword}, '%')
             OR t.remark LIKE CONCAT('%', #{q.keyword}, '%') OR t.source_no LIKE CONCAT('%', #{q.keyword}, '%') OR t.partner_name LIKE CONCAT('%', #{q.keyword}, '%')
             OR c.name LIKE CONCAT('%', #{q.keyword}, '%') OR s.name LIKE CONCAT('%', #{q.keyword}, '%'))

    AND t.doc_date >= #{q.beginDate}
    AND t.doc_date <= #{q.endDate}

ORDER BY t.doc_date DESC, t.id DESC

SELECT x.* FROM (
SELECT i.id AS id, t.id AS doc_id, NULL AS transfer_id, t.doc_no AS doc_no, t.doc_date AS doc_date, t.direction AS direction, t.ticket_no AS ticket_no, AS partner_label, t.settle_method AS settle_method, CONCAT(a.code, ' ', a.name) AS account_name, g.name AS category_name, i.amount AS amount, i.remark AS remark FROM fin_io_doc_item i JOIN fin_io_doc t ON t.id = i.doc_id JOIN fin_io_category g ON g.id = i.category_id
LEFT JOIN fin_account a ON a.id = t.account_id WHERE t.status = #{status} AND t.doc_date >= #{begin} AND t.doc_date <= #{end} AND t.direction = #{direction} AND i.category_id = #{categoryId}
UNION ALL
SELECT f.id AS id, NULL AS doc_id, f.id AS transfer_id, f.transfer_no AS doc_no, f.transfer_date AS doc_date, 'OUT' AS direction, f.ticket_no AS ticket_no, NULL AS partner_label, NULL AS settle_method, CONCAT(a.code, ' ', a.name) AS account_name, NULL AS category_name, f.fee AS amount, f.remark AS remark FROM fin_fund_transfer f LEFT JOIN fin_account a ON a.id = CASE WHEN f.fee_bearer = 'TO' THEN f.to_account_id ELSE f.from_account_id END WHERE f.fee > 0 AND f.transfer_date >= #{begin} AND f.transfer_date <= #{end}
) x ORDER BY x.doc_date DESC, x.doc_no DESC, x.id
